const r = await $`grep -rlE "retryPolicy|maxAttempts: 3" src test`;
const files = r.stdout.split('\n').filter(Boolean);
const fs = require('node:fs');
for (const f of files) {
  let s = fs.readFileSync(f,'utf8');
  s = s.replace(/retryPolicy/g,'backoffPolicy').replace(/maxAttempts: 3\b/g,'maxAttempts: 5');
  fs.writeFileSync(f,s);
}
const t = await $`node --test 2>&1 | tail -30`;
return {files, test: t.stdout};

